/**
 * Types for the admin-governance objects added in the 20260907* migrations.
 *
 * `types.ts` is generated by the Supabase CLI and is marked do-not-edit. It is
 * also already stale — it predates the 20260903* migrations, so `disputes`,
 * `admin_cancel_booking` and `messages.is_hidden` are all missing from it too.
 * Rather than hand-patch a generated file, the new surface is declared here and
 * reached through the narrow `governanceRpc` / `governanceTable` helpers below.
 *
 * When someone next runs `supabase gen types`, everything in this file becomes
 * redundant: delete it and let the hooks import from `types.ts` instead.
 */

import type { PostgrestError } from "@supabase/supabase-js";

import { supabase } from "@/integrations/supabase/client";

/** `app_role` after 20260907090000 added the top tier. */
export type GovernanceRole = "student" | "parent" | "tutor" | "agency" | "admin" | "super_admin";

export type AdminInvitationStatus = "pending" | "accepted" | "revoked" | "expired";

export type AdminRequestStatus = "pending" | "approved" | "rejected" | "executed" | "failed";

/** The five actions that require a second approver. */
export type AdminRequestAction =
  | "payment.refund"
  | "booking.cancel_with_refund"
  | "payout.settle"
  | "user_roles.grant_elevated"
  | "profile.suspend";

